import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.DaAAbehN.js";const u=JSON.parse('{"title":"Project 1: Organize Your Computer (Beginner Level)","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/module-5/project-1.md","filePath":"en/modules/module-5/project-1.md"}'),o={name:"en/modules/module-5/project-1.md"};function i(l,e,p,r,d,c){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="project-1-organize-your-computer-beginner-level" tabindex="-1">Project 1: Organize Your Computer (Beginner Level) <a class="header-anchor" href="#project-1-organize-your-computer-beginner-level" aria-label="Permalink to &quot;Project 1: Organize Your Computer (Beginner Level)&quot;">​</a></h1><blockquote><p>📌 <strong>Learning Objectives</strong>: Master Codex&#39;s File Operations and natural language command abilities by organizing a computer folder ⏱️ <strong>Estimated Time</strong>: 20 minutes 🎯 <strong>Skills learned</strong>: File Operations, natural language commands, permission management</p></blockquote><hr><h2 id="i-task-description" tabindex="-1">I. Task Description <a class="header-anchor" href="#i-task-description" aria-label="Permalink to &quot;I. Task Description&quot;">​</a></h2><p>Use Codex to analyze and organize a messy downloads folder on your computer.</p><hr><h2 id="ii-preparation" tabindex="-1">II. Preparation <a class="header-anchor" href="#ii-preparation" aria-label="Permalink to &quot;II. Preparation&quot;">​</a></h2><ol><li>Create a test folder on your computer named &quot;Folder to Organize&quot;</li><li>Put some different types of files inside it (if you don&#39;t have real files, just create a few manually): <ul><li>A few text files (.txt)</li><li>A few image files (.jpg, .png)</li><li>A few PDF files</li><li>A few Excel files (.xlsx)</li><li>A few archive files (.zip)</li></ul></li><li>You can also use your computer&#39;s actual &quot;Downloads&quot; folder (recommended: copy it to the desktop first as a test).</li></ol><hr><h2 id="iii-operation-steps" tabindex="-1">III. Operation Steps <a class="header-anchor" href="#iii-operation-steps" aria-label="Permalink to &quot;III. Operation Steps&quot;">​</a></h2><h3 id="step-1-set-the-folder-as-codex-s-workspace" tabindex="-1">Step 1: Set the Folder as Codex&#39;s Workspace <a class="header-anchor" href="#step-1-set-the-folder-as-codex-s-workspace" aria-label="Permalink to &quot;Step 1: Set the Folder as Codex&#39;s Workspace&quot;">​</a></h3><ol><li>Open the Codex desktop app</li><li>Click &quot;Open Folder&quot; or &quot;Select Workspace&quot;</li><li>Find your &quot;Folder to Organize&quot; and confirm.</li></ol><h3 id="step-2-have-codex-analyze-the-folder" tabindex="-1">Step 2: Have Codex Analyze the Folder <a class="header-anchor" href="#step-2-have-codex-analyze-the-folder" aria-label="Permalink to &quot;Step 2: Have Codex Analyze the Folder&quot;">​</a></h3><p>Type this into the chat box:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Please help me analyze this folder. Tell me:</span></span>
<span class="line"><span>1. How many files are there in total?</span></span>
<span class="line"><span>2. How many of each file type?</span></span>
<span class="line"><span>3. What are the three largest files?</span></span></code></pre></div><p>Observe Codex&#39;s output to understand the folder&#39;s current state.</p><h3 id="step-3-have-codex-organize-the-folder" tabindex="-1">Step 3: Have Codex Organize the Folder <a class="header-anchor" href="#step-3-have-codex-organize-the-folder" aria-label="Permalink to &quot;Step 3: Have Codex Organize the Folder&quot;">​</a></h3><p>Type this command:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Please organize this folder by file type:</span></span>
<span class="line"><span>- Image files (.jpg, .png, .gif) → move to images folder</span></span>
<span class="line"><span>- Document files (.pdf, .docx, .doc) → move to documents folder</span></span>
<span class="line"><span>- Spreadsheet files (.xlsx, .xls, .csv) → move to spreadsheets folder</span></span>
<span class="line"><span>- Text files (.txt, .md) → move to text-files folder</span></span>
<span class="line"><span>- Archive files (.zip, .rar, .7z) → move to archives folder</span></span>
<span class="line"><span>- Other files → move to other folder</span></span>
<span class="line"><span>Please tell me your plan first, and wait for my confirmation before executing.</span></span></code></pre></div><h3 id="step-4-review-codex-s-plan" tabindex="-1">Step 4: Review Codex&#39;s Plan <a class="header-anchor" href="#step-4-review-codex-s-plan" aria-label="Permalink to &quot;Step 4: Review Codex&#39;s Plan&quot;">​</a></h3><p>Codex will list its organization plan, for example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>My organization plan:</span></span>
<span class="line"><span>1. Create the following subfolders: images/, documents/, spreadsheets/, text-files/, archives/, other/</span></span>
<span class="line"><span>2. Scan all files and classify by extension</span></span>
<span class="line"><span>3. Move each file to the corresponding subfolder</span></span>
<span class="line"><span>Please confirm whether to start execution?</span></span></code></pre></div><p>Click &quot;Allow&quot; or type &quot;Start.&quot;</p><h3 id="step-5-verify-the-results" tabindex="-1">Step 5: Verify the Results <a class="header-anchor" href="#step-5-verify-the-results" aria-label="Permalink to &quot;Step 5: Verify the Results&quot;">​</a></h3><p>After organizing, check whether the folder structure is correct:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Folder to Organize/</span></span>
<span class="line"><span>├── images/</span></span>
<span class="line"><span>│   ├── photo1.jpg</span></span>
<span class="line"><span>│   └── screenshot.png</span></span>
<span class="line"><span>├── documents/</span></span>
<span class="line"><span>│   └── report.pdf</span></span>
<span class="line"><span>├── spreadsheets/</span></span>
<span class="line"><span>│   └── data.xlsx</span></span>
<span class="line"><span>├── text-files/</span></span>
<span class="line"><span>│   └── notes.txt</span></span>
<span class="line"><span>├── archives/</span></span>
<span class="line"><span>│   └── backup.zip</span></span>
<span class="line"><span>└── other/</span></span>
<span class="line"><span>    └── unknown.file</span></span></code></pre></div><hr><h2 id="iv-advanced-challenges" tabindex="-1">IV. Advanced Challenges <a class="header-anchor" href="#iv-advanced-challenges" aria-label="Permalink to &quot;IV. Advanced Challenges&quot;">​</a></h2><p>If the above task is too easy, try these advanced commands:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Find all files larger than 10MB and put them in a separate &quot;large-files&quot; folder.</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Count how many files have duplicate names (ignoring extensions) in this folder.</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me generate a folder organization report and save it to reports.md.</span></span></code></pre></div><hr><h2 id="v-summary" tabindex="-1">V. Summary <a class="header-anchor" href="#v-summary" aria-label="Permalink to &quot;V. Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill Learned</th><th>How It Shows</th></tr></thead><tbody><tr><td>File Operations</td><td>Read, classify, move files</td></tr><tr><td>Natural language commands</td><td>Describe organization rules in natural language</td></tr><tr><td>Permission management</td><td>Observe how Codex asks for your approval</td></tr><tr><td>Result verification</td><td>Check whether the organization results meet expectations</td></tr></tbody></table><hr><h2 id="vi-next-step" tabindex="-1">VI. Next Step <a class="header-anchor" href="#vi-next-step" aria-label="Permalink to &quot;VI. Next Step&quot;">​</a></h2><p><a href="./project-2.html">→ Project 2: Create a PPT Report</a></p>`,38)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
